-- test/fixtures.sql
--
-- The table every pattern in sql/patterns runs against. Hand written for this
-- repository: 50 customers and 500 orders generated by the statements below.
-- No row here came from anywhere else, and 500 rows is enough to exercise a
-- batched backfill at a batch size of 100 and small enough that a pattern run
-- is not a load test. Nothing in this repository has measured a migration
-- against a table of a size where any of this hurts.
--
-- The columns are laid out so the seven patterns do not collide: each one owns
-- the column it changes, which is why they can be applied one after another to
-- the same database.
--
--   shipping_country  pattern 02 makes it NOT NULL
--   customer_id       pattern 03 indexes it, pattern 06 adds its foreign key
--   reference         pattern 03 makes it unique, pattern 04 widens it
--   legacy_amount     pattern 04 widens it the expensive way
--   note              pattern 05 renames it
--   status            pattern 07 changes its default

CREATE SCHEMA IF NOT EXISTS app;

CREATE TABLE app.customers (
    customer_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email       varchar(64) NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE app.orders (
    order_id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id      bigint NOT NULL,
    reference        varchar(32) NOT NULL,
    legacy_amount    integer NOT NULL,
    status           text NOT NULL,
    shipping_country varchar(2),
    note             text,
    placed_at        timestamptz NOT NULL DEFAULT now()
);

INSERT INTO app.customers (email)
SELECT format('c%s@example.test', g) FROM generate_series(1, 50) AS g;

-- One row in seven has no shipping_country, which is what pattern 02 has to
-- deal with before it can set NOT NULL, and one in eleven has no note.
INSERT INTO app.orders (customer_id, reference, legacy_amount, status, shipping_country, note)
SELECT 1 + (g % 50),
       'REF-' || lpad(g::text, 6, '0'),
       (g * 137) % 90000,
       CASE WHEN g % 5 = 0 THEN 'shipped' ELSE 'placed' END,
       CASE WHEN g % 7 = 0 THEN NULL ELSE 'GB' END,
       CASE WHEN g % 11 = 0 THEN NULL ELSE format('note %s', g) END
  FROM generate_series(1, 500) AS g;

-- A partitioned table for pattern 08, with two quarters attached and a third
-- sitting beside it waiting to be. 300 events, 100 per quarter.
CREATE TABLE app.events (
    event_id    bigint GENERATED BY DEFAULT AS IDENTITY,
    occurred_at date NOT NULL,
    kind        text NOT NULL,
    payload     text NOT NULL
) PARTITION BY RANGE (occurred_at);

-- A partitioned index, because the index is half the cost of an attach: any
-- index the parent has and the partition lacks is created during ATTACH, while
-- the lock is held.
CREATE INDEX events_kind_idx ON app.events (kind);

CREATE TABLE app.events_2026q1 PARTITION OF app.events
    FOR VALUES FROM ('2026-01-01') TO ('2026-04-01');

CREATE TABLE app.events_2026q2 PARTITION OF app.events
    FOR VALUES FROM ('2026-04-01') TO ('2026-07-01');

-- Not a partition yet. Pattern 08 attaches it.
CREATE TABLE app.events_2026q3 (LIKE app.events INCLUDING DEFAULTS INCLUDING CONSTRAINTS);

INSERT INTO app.events (occurred_at, kind, payload)
    SELECT date '2026-01-01' + (g % 90), 'placed', 'e' || g
      FROM generate_series(1, 100) AS g;

INSERT INTO app.events (occurred_at, kind, payload)
    SELECT date '2026-04-01' + (g % 91), 'placed', 'e' || g
      FROM generate_series(1, 100) AS g;

INSERT INTO app.events_2026q3 (event_id, occurred_at, kind, payload)
    SELECT 10000 + g, date '2026-07-01' + (g % 92), 'placed', 'e' || g
      FROM generate_series(1, 100) AS g;

ANALYZE app.customers;
ANALYZE app.orders;
ANALYZE app.events;
ANALYZE app.events_2026q3;
